const allItems = $input.all();
const jobs = [];
const now = new Date();
const MAX_JOB_AGE_HOURS = 30;

function cleanText(value) {
  return String(value || '')
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

function parseDate(value) {
  if (!value) return null;
  let date;
  if (typeof value === 'number') {
    date = new Date(value < 1000000000000 ? value * 1000 : value);
  } else {
    const numeric = Number(value);
    if (String(value).trim() !== '' && Number.isFinite(numeric) && numeric > 1000000000) {
      date = new Date(numeric < 1000000000000 ? numeric * 1000 : numeric);
    } else {
      date = new Date(value);
    }
  }
  return Number.isNaN(date.getTime()) ? null : date;
}

function toArray(value) {
  if (Array.isArray(value)) return value;
  if (typeof value === 'string') return value.split(',').map(x => x.trim()).filter(Boolean);
  return [];
}

for (const item of allItems) {
  const response = item.json || {};
  const isArbeitnow = Array.isArray(response.data);
  const isRemotive = Array.isArray(response.jobs);

  if (isArbeitnow) {
    for (const job of response.data) {
      jobs.push({
        source: 'Arbeitnow',
        company: job.company_name || job.company || 'Unknown Company',
        title: job.title || '',
        location: job.location || 'Unknown',
        workMode: job.remote ? 'Remote' : 'On-site / Hybrid',
        description: job.description || '',
        skills: toArray(job.tags),
        publishedAt: parseDate(job.created_at),
        applicationUrl: job.url || '',
        salary: job.salary || 'Not Disclosed',
        jobReferenceId: job.slug || job.id || ''
      });
    }
  }

  if (isRemotive) {
    for (const job of response.jobs) {
      const requiredLocation = String(job.candidate_required_location || '').toLowerCase();
      const isIndiaAllowed = !requiredLocation ||
        requiredLocation.includes('india') ||
        requiredLocation.includes('worldwide') ||
        requiredLocation.includes('anywhere') ||
        requiredLocation.includes('all countries');

      if (!isIndiaAllowed) continue;

      jobs.push({
        source: 'Remotive',
        company: job.company_name || 'Unknown Company',
        title: job.title || '',
        location: job.candidate_required_location || 'Remote (India / Worldwide)',
        workMode: 'Remote',
        description: job.description || '',
        skills: toArray(job.tags),
        publishedAt: parseDate(job.publication_date),
        applicationUrl: job.url || '',
        salary: job.salary || 'Not Disclosed',
        jobReferenceId: String(job.id || '')
      });
    }
  }
}

const output = [];
const seen = new Set();

for (const job of jobs) {
  const title = cleanText(job.title);
  const company = cleanText(job.company);
  const location = cleanText(job.location);
  const description = cleanText(job.description);
  const applicationUrl = String(job.applicationUrl || '').trim();
  const publishedAt = job.publishedAt;

  if (!title || !company || !applicationUrl || !publishedAt) continue;
  if (!/^https?:\/\//i.test(applicationUrl)) continue;

  const ageHours = (now.getTime() - publishedAt.getTime()) / 3600000;
  if (ageHours < -1 || ageHours > MAX_JOB_AGE_HOURS) continue;

  const normalizedKey = `${company.toLowerCase()}|${title.toLowerCase()}|${applicationUrl.split('?')[0].toLowerCase()}`;
  if (seen.has(normalizedKey)) continue;
  seen.add(normalizedKey);

  let freshnessScore = 60;
  let freshnessTier = '24_30_HOURS';
  if (ageHours <= 1) {
    freshnessScore = 100;
    freshnessTier = '0_1_HOUR';
  } else if (ageHours <= 3) {
    freshnessScore = 95;
    freshnessTier = '1_3_HOURS';
  } else if (ageHours <= 6) {
    freshnessScore = 90;
    freshnessTier = '3_6_HOURS';
  } else if (ageHours <= 12) {
    freshnessScore = 85;
    freshnessTier = '6_12_HOURS';
  } else if (ageHours <= 24) {
    freshnessScore = 75;
    freshnessTier = '12_24_HOURS';
  }

  output.push({
    json: {
      source: job.source,
      company,
      title,
      location,
      workMode: job.workMode,
      description: description.slice(0, 12000),
      skills: job.skills,
      publishedAt: publishedAt.toISOString(),
      discoveredAt: now.toISOString(),
      jobAgeHours: Number(ageHours.toFixed(2)),
      freshnessScore,
      freshnessTier,
      applicationUrl,
      salary: job.salary,
      jobReferenceId: job.jobReferenceId
    }
  });
}

return output;

const SENIORITY_BLACKLIST = [
  'senior', 'sr.', 'lead', 'principal', 'staff engineer',
  'architect', 'engineering manager', 'director', 'vp', 'tech lead'
];

const NON_DEVELOPER_BLACKLIST = [
  'customer support', 'call center', 'sales executive', 'marketing',
  'hr executive', 'accountant', 'data entry', 'desktop support',
  'network engineer', 'mechanical engineer', 'civil engineer'
];

const output = [];

for (const item of $input.all()) {
  const job = item.json || {};
  const title = String(job.title || '').toLowerCase();
  const description = String(job.description || '').toLowerCase();

  if (SENIORITY_BLACKLIST.some(term => title.includes(term))) continue;
  if (NON_DEVELOPER_BLACKLIST.some(term => title.includes(term))) continue;

  const experienceText = `${title} ${description}`;
  const yearsMatches = [...experienceText.matchAll(/(?:minimum|min\.?|at least|required|requires)\s*(\d+)\s*\+?\s*years?/gi)];
  if (yearsMatches.some(match => Number(match[1]) >= 3)) continue;

  if (!job.applicationUrl || !job.applicationUrl.startsWith('http')) continue;

  const hasRelevantKeyword = /java|spring|backend|software engineer|software developer|full.?stack|programmer|application developer/i.test(title);
  if (!hasRelevantKeyword) continue;

  output.push({ json: job });
}

return output;

const responseItems = $input.all();
const originalJobs = $('Pre-AI Rule-Based Filter').all();
const output = [];

for (let i = 0; i < responseItems.length; i++) {
  const response = responseItems[i].json || {};
  const job = originalJobs[i]?.json || {};
  let evaluation = null;
  let evaluationSucceeded = false;

  try {
    const text = response.candidates?.[0]?.content?.parts?.map(p => p.text || '').join('');
    if (!text) throw new Error('Gemini returned no content');

    evaluation = JSON.parse(text);
    if (typeof evaluation.isEligible !== 'boolean') throw new Error('Missing isEligible');
    if (!Number.isFinite(Number(evaluation.matchScore))) throw new Error('Invalid matchScore');

    evaluation.matchScore = Math.max(0, Math.min(100, Number(evaluation.matchScore)));
    evaluation.confidence = Math.max(0, Math.min(100, Number(evaluation.confidence || 0)));
    evaluationSucceeded = true;
  } catch (error) {
    evaluation = {
      isEligible: false,
      rejectReason: 'Gemini evaluation failed. Manual review required.',
      matchScore: 0,
      matchLevel: 'Not Evaluated',
      matchedSkills: [],
      missingSkills: [],
      candidateExperienceSuitable: false,
      whyMatched: 'No notification will be sent because evaluation was unsuccessful.',
      confidence: 0
    };
  }

  const matchScore = evaluation.matchScore;
  const jobAgeHours = Number(job.jobAgeHours || 999);
  const eligible = evaluationSucceeded && evaluation.isEligible === true && evaluation.candidateExperienceSuitable === true && matchScore >= 65;

  let priorityLevel = 'STORE_ONLY';
  let shouldEmail = false;

  if (eligible) {
    if (jobAgeHours <= 3 && matchScore >= 75) {
      priorityLevel = 'URGENT';
      shouldEmail = true;
    } else if (jobAgeHours <= 6 && matchScore >= 85) {
      priorityLevel = 'HIGH_PRIORITY';
      shouldEmail = true;
    } else if (matchScore >= 65) {
      priorityLevel = matchScore >= 85 ? 'EXCELLENT' : matchScore >= 75 ? 'STRONG' : 'GOOD';
      shouldEmail = true;
    }
  }

  output.push({
    json: {
      ...job,
      evaluation,
      evaluationSucceeded,
      matchScore,
      priorityLevel,
      shouldEmail
    }
  });
}

return output;

const job = $json;
const evaluation = job.evaluation || {};

function escapeHtml(value) {
  return String(value || '').replace(/[&<>\"']/g, ch => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', "'": '&#39;'
  }[ch]));
}

const matchedSkills = (evaluation.matchedSkills || [])
  .map(skill => `<span style="display:inline-block;background:#dcfce7;color:#166534;padding:4px 8px;border-radius:5px;margin:3px;">✓ ${escapeHtml(skill)}</span>`)
  .join(' ');

const priority = job.priorityLevel === 'URGENT' ? '🔥 URGENT' :
  job.priorityLevel === 'HIGH_PRIORITY' ? '⚡ HIGH PRIORITY' : '✨ MATCHED JOB';

const html = `
<div style="font-family:Arial,sans-serif;max-width:650px;margin:auto;border:1px solid #ddd;border-radius:12px;overflow:hidden;">
  <div style="background:#0f172a;color:white;padding:24px;">
    <h2 style="margin:0 0 8px;">${escapeHtml(job.title)}</h2>
    <p style="margin:0;color:#cbd5e1;">${escapeHtml(job.company)} | ${escapeHtml(job.location)} | ${escapeHtml(job.workMode)}</p>
    <p style="margin-top:12px;font-weight:bold;">${priority}</p>
  </div>
  <div style="padding:24px;">
    <h2 style="color:#2563eb;">${job.matchScore}/100 Match</h2>
    <p><strong>Posted:</strong> ${job.jobAgeHours} hours ago</p>
    <p><strong>Salary:</strong> ${escapeHtml(job.salary || 'Not Disclosed')}</p>
    <h3>Why it matches</h3>
    <p>${escapeHtml(evaluation.whyMatched || 'Review the job details and requirements.')}</p>
    <h3>Matched skills</h3>
    <div>${matchedSkills || 'No matched skills listed.'}</div>
    <p style="margin-top:24px;text-align:center;">
      <a href="${escapeHtml(job.applicationUrl)}" target="_blank" rel="noopener noreferrer" style="background:#2563eb;color:white;padding:14px 24px;text-decoration:none;border-radius:8px;font-weight:bold;">View Job & Apply</a>
    </p>
  </div>
  <div style="background:#f8fafc;padding:14px;text-align:center;font-size:12px;color:#64748b;">AI Job Recommendation Agent | Always verify details on the employer's official portal.</div>
</div>`;

const subjectPrefix = job.priorityLevel === 'URGENT' ? '🔥 Apply Soon' :
  job.priorityLevel === 'HIGH_PRIORITY' ? '⚡ High Priority' : 'New Job Match';

return {
  json: {
    ...job,
    emailSubject: `${subjectPrefix}: ${job.title} at ${job.company} (${job.matchScore}% Match)`,
    emailHtml: html
  }
};
